import { useState } from "react";
import axios from "axios";

function App() {
  const [input, setInput] = useState("");
  const [response, setResponse] = useState("");

  const handleSend = async () => {
    try {
      const res = await axios.post("http://localhost:5000/chat", {
        prompt: input,
      });
      setResponse(res.data.response.parts[0].text);
    } catch (error) {
      console.error("Error:", error);
      setResponse("Error fetching response. Check console.");
    }
  };

  const handleClear = () => {
    setInput("");
    setResponse("");
  };

  return (
    <div style={{ textAlign: "center", marginTop: "50px" }}>
      <h2>AI Tutor</h2>
      <textarea
        rows="4"
        cols="50"
        value={input}
        onChange={(e) => setInput(e.target.value)}
        placeholder="Ask me anything..."
      />
      <br />
      <button onClick={handleSend} style={{ marginTop: "10px", marginRight: "10px" }}>
        Ask AI
      </button>
      <button onClick={handleClear} style={{ marginTop: "10px", background: "red", color: "white" }}>
        Clear Chat
      </button>
      <h3>Response:</h3>
      <p style={{ whiteSpace: "pre-wrap", textAlign: "left", maxWidth: "600px", margin: "auto" }}>{response}</p>
    </div>
  );
}

export default App;
